-- ==========================================================================
-- SCRIPT RESTORE MASSAL 39 SISWA DAPODIK (15 KELAS) TA 2026/2027
-- Sumber: Data Siswa Dapodik Perkelas TA 2026-2027.xlsx
-- Target: Tabel `siswa` dan `orangtua_wali` (Database: raporsmpit)
-- Catatan: Menggunakan INSERT INTO ... ON DUPLICATE KEY UPDATE & SET FOREIGN_KEY_CHECKS=0
-- ==========================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- 1. BERSIHKAN RECORD DANGLING ANGGOTA_ROMBEL
DELETE FROM anggota_rombel WHERE id IN (747, 749, 615);

-- 2. RESTORE DATA SISWA KE TABEL SISWA (39 SISWA)
ON DUPLICATE KEY UPDATE rombel_id=VALUES(rombel_id), status_siswa=VALUES(status_siswa), nama_lengkap=VALUES(nama_lengkap), nis=VALUES(nis), nisn=VALUES(nisn), nik=VALUES(nik);

-- 3. RESTORE DATA ORANG TUA KE TABEL ORANGTUA_WALI
DELETE FROM orangtua_wali WHERE siswa_id IN (
    540, 550, 551, 451, 453, 461, 439, 440, 454, 629, 630, 6, 29, 36, 39, 
    40, 46, 51, 52, 54, 68, 74, 91, 94, 99, 164, 166, 176, 187, 137, 
    208, 209, 211, 222, 233, 243, 246, 256, 267
);

;

SET FOREIGN_KEY_CHECKS = 1;
